    private static GridModel Model(string name) => name switch
    {
        "9" => IeeeCases.Case9(),
        "14" => IeeeCases.Case14(),
        "30" => IeeeCases.Case30(),
        "57" => IeeeCases.Case57(),
        "118" => IeeeCases.Case118(),
        "300" => IeeeCases.Case300(),
        "24" => IeeeCases.Case24Rts(),
        "145" => IeeeCases.Case145(),
        _ => throw new ArgumentException(name),
    };

    [Theory]
    [InlineData("14", 14, 5, 20)]
    [InlineData("30", 30, 6, 41)]
    [InlineData("57", 57, 7, 80)]
    [InlineData("118", 118, 54, 186)]
    [InlineData("300", 300, 69, 411)]
    [InlineData("24", 24, 33, 38)]
    [InlineData("145", 145, 50, 453)]
    public void Has_expected_dimensions(string name, int buses, int gens, int branches)
    {
        var m = Model(name);
        Assert.Equal(buses, m.BusCount);
        Assert.Equal(gens, m.Generators.Count);
        Assert.Equal(branches, m.Branches.Count);
        Assert.Equal(100, m.BaseMva);
        Assert.Single(m.Buses, b => b.Type == BusType.Slack);  // exactly one slack
    }

    [Theory]
    [InlineData("14")]
    [InlineData("30")]
    [InlineData("57")]
    [InlineData("118")]
    [InlineData("300")]
    [InlineData("24")]
    [InlineData("145")]
    public void Converges_and_balances(string name)
    {
        var m = Model(name);
        var r = new NewtonRaphsonPowerFlow().Solve(m);

        Assert.True(r.Converged, $"case{name} did not converge");
        Assert.True(r.MaxMismatch < 1e-6, $"case{name} mismatch {r.MaxMismatch:E2}");

        // Net injections sum to the total losses (generation = load + losses).
        double load = m.Buses.Sum(b => b.Pd);
        Assert.Equal(r.TotalLossMw, r.PInjMw.Sum(), 3);
        Assert.True(r.TotalLossMw >= 0, $"case{name} negative losses");
    }

    // Per-case tolerances: ~2x the observed deviation from the stored solution. The stored
    // classic case300 angles are only roughly converged, so its angle bound is deliberately loose;
    // its voltages (and everything else) still match tightly.
    [Fact] public void Case14_matches_published() => AssertPublished(Model("14"), Case14Vm, Case14Va, 0.005, 0.2);
    [Fact] public void Case57_matches_published() => AssertPublished(Model("57"), Case57Vm, Case57Va, 0.02, 1.5);
    [Fact] public void Case118_matches_published() => AssertPublished(Model("118"), Case118Vm, Case118Va, 0.03, 1.0);
    [Fact] public void Case300_matches_published() => AssertPublished(Model("300"), Case300Vm, Case300Va, 0.02, 12.0);
    [Fact] public void Case145_matches_published() => AssertPublished(Model("145"), Case145Vm, Case145Va, 0.01, 0.1);

    /// <summary>
    /// Solve the case and check every bus voltage against the source's stored solved value.
    /// Angles are re-referenced to the slack bus (the source's angle reference need not be it).
    /// </summary>
    private static void AssertPublished(GridModel m, double[] expVm, double[] expVa, double vmTol, double vaTol)
    {
        var r = new NewtonRaphsonPowerFlow().Solve(m);
        Assert.True(r.Converged, "did not converge");

        var vm = new Dictionary<int, double>(r.BusIds.Count);
        var va = new Dictionary<int, double>(r.BusIds.Count);
        for (int i = 0; i < r.BusIds.Count; i++) { vm[r.BusIds[i]] = r.Vm[i]; va[r.BusIds[i]] = r.VaDeg[i]; }

        int slackIdx = 0;
        for (int i = 0; i < m.Buses.Count; i++) if (m.Buses[i].Type == BusType.Slack) { slackIdx = i; break; }
        double offset = expVa[slackIdx];                 // slack angle in the stored reference frame
        double solvedSlack = va[m.Buses[slackIdx].Id];   // slack angle in the solved frame (the solver
                                                         // pins it to the bus's specified Va, not 0)

        for (int i = 0; i < m.Buses.Count; i++)
        {
            int id = m.Buses[i].Id;
            Assert.True(Math.Abs(vm[id] - expVm[i]) < vmTol,
                $"bus {id}: Vm {vm[id]:F4} vs published {expVm[i]:F4}");
            // Compare angles with both sides referenced to the slack bus.
            double dva = (va[id] - solvedSlack) - (expVa[i] - offset);
            Assert.True(Math.Abs(dva) < vaTol,
                $"bus {id}: Va {va[id] - solvedSlack:F3} vs published {expVa[i] - offset:F3} (deg)");
        }
    }
}
